                unsafe H.halfVector(clamping: a, shiftedRightByUnchecked: bits),
                H.HalfVector(
                    raw: HighwayReference.halfVectorClampingShiftedRightByI32ToU16(
                        a.raw,
                        Int32(truncatingIfNeeded: bits)
                    )
                ),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

